/**
 * @summary Get the settings
 */

export function useGetItemSettings<TData = Awaited<ReturnType<typeof getItemSettings>>, TError = AxiosError<unknown>>(
 universe: string, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof getItemSettings>>, TError, TData>>, axios?: AxiosRequestConfig}
 , queryClient?: QueryClient 
 ):  UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> } {

  const queryOptions = getGetItemSettingsQueryOptions(universe,options)

  const query = useQuery(queryOptions, queryClient) as  UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> };

  query.queryKey = queryOptions.queryKey ;

  return query;
}



/**
 * @summary Update the settings
 */
export const updateItemSettings = (
    universe: string,
    itemSettings: ItemSettings, options?: AxiosRequestConfig
 ): Promise<AxiosResponse<void>> => {
    
    
    return axios.put(
      `/api/${universe}/universe-settings/item`,
      itemSettings,options
    );
  }



export const getUpdateItemSettingsMutationOptions = <TError = AxiosError<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateItemSettings>>, TError,{universe: string;data: ItemSettings}, TContext>, axios?: AxiosRequestConfig}
): UseMutationOptions<Awaited<ReturnType<typeof updateItemSettings>>, TError,{universe: string;data: ItemSettings}, TContext> => {

const mutationKey = ['updateItemSettings'];
const {mutation: mutationOptions, axios: axiosOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, axios: undefined};

      


      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateItemSettings>>, {universe: string;data: ItemSettings}> = (props) => {
          const {universe,data} = props ?? {};

          return  updateItemSettings(universe,data,axiosOptions)
        }

        


  return  { mutationFn, ...mutationOptions }}

    export type UpdateItemSettingsMutationResult = NonNullable<Awaited<ReturnType<typeof updateItemSettings>>>
    export type UpdateItemSettingsMutationBody = ItemSettings
